import math
def power(previous,current,seconds,range_uj,bound_watts,previous_epoch,current_epoch):
    if type(range_uj) is not int or range_uj<=0 or any(type(value) is not int or not 0<=value<range_uj for value in (previous,current)):raise ValueError('bounded raw microjoule readings required')
    if any(type(value) not in (int,float) or not math.isfinite(value) or value<=0 for value in (seconds,bound_watts)):raise ValueError('positive finite interval and trusted bound required')
    if not previous_epoch or not current_epoch:return dict(status='unknown_epoch',watts=None)
    if previous_epoch!=current_epoch:return dict(status='reset',watts=None)
    if bound_watts*seconds>=range_uj/1000000:return dict(status='ambiguous',watts=None)
    delta=(current-previous)%range_uj
    watts=delta/1000000/seconds
    if watts>bound_watts:return dict(status='inconsistent',watts=None)
    return dict(status='wrapped' if current<previous else 'ok',watts=watts)
